// ---------- web search (server-side: no CORS) ----------
async function fetchT(url, opts, ms) {
  const c = new AbortController(); const t = setTimeout(() => c.abort(), ms || 15000);
  try { return await fetch(url, { ...(opts || {}), signal: c.signal }); } finally { clearTimeout(t); }
}
async function webSearch(q) {
  // 1) Tavily if key
  if (TAVILY) {
    try {
      const r = await fetchT('https://api.tavily.com/search', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ api_key: TAVILY, query: q, max_results: 6, include_answer: true, search_depth: 'advanced' })
      });
      if (r.ok) { const j = await r.json();
        return JSON.stringify({ answer: j.answer || '', results: (j.results || []).map(x => ({ title: x.title, url: x.url, snippet: (x.content || '').slice(0, 350) })) }); }
    } catch {}
  }
  // 2) DuckDuckGo instant answer (free, no key)
  try {
    const r = await fetchT('https://api.duckduckgo.com/?format=json&no_html=1&q=' + encodeURIComponent(q));
    if (r.ok) { const j = await r.json(); const bits = [];
      if (j.AbstractText) bits.push(j.AbstractText + (j.AbstractURL ? ' — ' + j.AbstractURL : ''));
      (j.RelatedTopics || []).slice(0, 6).forEach(t => { if (t.Text) bits.push(t.Text + (t.FirstURL ? ' — ' + t.FirstURL : '')); });
      if (bits.length) return bits.join('\n'); }
  } catch {}
  return 'No results. Consider adding a free TAVILY_KEY for reliable search.';
}
// ---------- YouTube (no API key) ----------
// Datacenter IPs (like Render's) get YouTube's cookie-consent wall instead of
// real results, which is why searches used to come back empty. The CONSENT
// cookie + hl/gl params + a real UA get past it. We also try a couple of
// mirrors so a single block doesn't kill playback.
const YT_HEADERS = {
  'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36',
  'Accept-Language': 'en-US,en;q=0.9',
  'Cookie': 'CONSENT=YES+cb.20210328-17-p0.en+FX+000'
};
function firstVideoId(html) {
  // prefer a real videoRenderer (an actual search result, not a thumbnail/ad)
  let m = /"videoRenderer":\{"videoId":"([a-zA-Z0-9_-]{11})"/.exec(html)
       || /\/watch\?v=([a-zA-Z0-9_-]{11})/.exec(html)
       || /"videoId":"([a-zA-Z0-9_-]{11})"/.exec(html);
  return m ? m[1] : null;
}
function titleNear(html, id) {
  const i = html.indexOf('"' + id + '"');
  if (i === -1) return null;
  const t = /"title":\{"runs":\[\{"text":"([^"]{1,120})"/.exec(html.slice(i, i + 800))
         || /"title":\{"simpleText":"([^"]{1,120})"/.exec(html.slice(i, i + 800));
  return t ? t[1].replace(/\\u0026/g, '&').replace(/\\"/g, '"') : null;
}
async function ytSearch(q) {
  const query = String(q || '').trim();
  const searchUrl = 'https://www.youtube.com/results?search_query=' + encodeURIComponent(query) + '&hl=en&gl=US';
  const tries = [
    searchUrl,
    'https://m.youtube.com/results?search_query=' + encodeURIComponent(query) + '&hl=en&gl=US',
    // proxy fallback: the jina reader fetches from ITS servers, so even if
    // YouTube blocks Render's IP entirely we still get the results page
    'https://r.jina.ai/' + searchUrl
  ];
  for (const url of tries) {
    try {
      const r = await fetchT(url, { headers: YT_HEADERS }, 14000);
      if (!r.ok) continue;
      const html = await r.text();
      const videoId = firstVideoId(html);
      if (videoId) {
        const title = (titleNear(html, videoId) || query).slice(0, 90);
        return { videoId, title, url: 'https://www.youtube.com/watch?v=' + videoId, query };
      }
    } catch (e) {}
  }
  // last resort: hand back the search page as a link
  return { videoId: null, title: query, url: 'https://www.youtube.com/results?search_query=' + encodeURIComponent(query), query };
}

let lastMedia = null;   // set by play_media during a brain run, returned to the app

async function readPage(url) {
  let u = String(url || '').trim(); if (!/^https?:\/\//i.test(u)) u = 'https://' + u;
  const r = await fetchT('https://r.jina.ai/' + u, { headers: { Accept: 'text/plain' } });
  if (!r.ok) throw new Error('read ' + r.status);
  return (await r.text()).slice(0, 6000);
}

