const ROSTER_FLAT = Object.entries(ROSTER).flatMap(([d, ns]) => ns.map(n => d + " / " + n));

let missions = loadJSON('missions.json', []);
let activeMission = null;              // mission id currently running
let missionQueue = Promise.resolve();  // one at a time — activeMission is global

function saveMissions() { missions = missions.slice(-40); saveJSON('missions.json', missions); }

function newMission(goal) {
  const m = { id: crypto.randomBytes(4).toString('hex'), goal, status: 'queued',
              started: Date.now(), steps: [], result: '', error: '' };
  missions.push(m); saveMissions(); return m;
}

function logWork(agent, dept, summary, output) {
  const m = missions.find(x => x.id === activeMission);
  if (!m) return 'No mission is running, so there was nothing to log against.';
  m.steps.push({ agent, dept: dept || '', summary: summary || '',
                 output: (output || '').slice(0, 1200), ts: Date.now() });
  saveMissions();
  return 'Logged to ' + agent + ' (step ' + m.steps.length + ').';
}

function missionBrief(goal) {
  return `MISSION: ${goal}

You are running this across Gavriel's agent map — 159 specialist agents in 10 departments.
Work the mission for real with your tools (web_search, read_page, browse_open, list_inbox, send_email...).

As you go, call log_work for EVERY meaningful piece of work, choosing the agent from the map whose
job it actually was. Use the exact agent name. This is what lights up his map, so log honestly:
one entry per real piece of work, with the actual finding in \`output\`, not a promise to do it.

Agents available:
${ROSTER_FLAT.join(', ')}

Finish with a short plain-language summary of what you found and what he should do next.`;
}

async function runMission(m) {
  activeMission = m.id;
  m.status = 'running'; saveMissions();
  try {
    m.result = await brain([{ role: 'user', content: missionBrief(m.goal) }], true);
    m.status = 'done';
  } catch (e) {
    m.status = 'failed'; m.error = e.message;
    console.error('mission ' + m.id + ' failed:', e.message);
  }
  m.finished = Date.now();
  activeMission = null;
  saveMissions();
}

// ---------- scheduled tasks (persistent cron) ----------
let tasks = loadJSON('tasks.json', []);
const jobs = new Map();
function armTask(t) {
  if (jobs.has(t.id)) { jobs.get(t.id).stop(); jobs.delete(t.id); }
  if (!t.active || !cron.validate(t.cron)) return;
  const job = cron.schedule(t.cron, () => runTask(t).catch(e => console.error('task', t.id, e.message)),
    { timezone: t.tz || process.env.TZ || 'America/New_York' });
  jobs.set(t.id, job);
}
async function runTask(t) {
  // A scheduled run has NO conversation context — only this instruction. So the
  // instruction must already contain every detail (who, what, when). It runs
  // autonomously with all her tools.
  t.lastRun = Date.now(); t.running = true; saveJSON('tasks.json', tasks);
  try {
    const out = await brain([{ role: 'user', content:
      'SCHEDULED TASK — run it fully and autonomously right now, no questions, no waiting for approval. ' +
      'Everything you need is in this instruction:\n\n' + t.instruction }], true);
    t.lastResult = (out || 'done').slice(0, 600);
    t.lastOk = true;
  } catch (e) {
    t.lastResult = 'ERROR: ' + e.message;
    t.lastOk = false;
    console.error('task', t.id, 'failed:', e.message);
  }
  t.running = false; saveJSON('tasks.json', tasks);
  if (t.count) { t.count -= 1; if (t.count <= 0) { t.active = false; armTask(t); saveJSON('tasks.json', tasks); } }
}
function scheduleTask(instruction, cronExpr, count) {
  if (!cron.validate(cronExpr)) throw new Error('bad cron: ' + cronExpr);
  const t = { id: crypto.randomBytes(4).toString('hex'), instruction, cron: cronExpr, count: count || null, active: true, ts: Date.now() };
  tasks.push(t); saveJSON('tasks.json', tasks); armTask(t); return t;
}
tasks.forEach(armTask); // re-arm on boot

