function mapHtml() {
  if (MAP_HTML) return MAP_HTML;
  try { return fs.readFileSync(path.join(__dirname, 'public', 'map.html'), 'utf8'); }
  catch { return '<!doctype html><h1>Map not found</h1>'; }
}
