app.post('/api/mission', auth, (req, res) => {
  const goal = String(req.body.goal || '').trim();
  if (!goal) return res.status(400).json({ error: 'goal required' });
  if (activeMission) return res.status(409).json({ error: 'a mission is already running', id: activeMission });
  const m = newMission(goal);
  // run it in the background and answer immediately — missions take minutes
  missionQueue = missionQueue.then(() => runMission(m)).catch(() => {});
  res.json({ id: m.id });
});

